1	import { z } from "zod";
2	import {
3	  extractLastValidObject,
4	  REFUSAL_REGEX,
5	  stripFences,
6	} from "./llm-reply";
7	import { type FactCategory, factCategoryValues } from "./schemas/facts";
8	
9	// The extraction contract, shaped by what makes memory pipelines survive
10	// unattended operation: the model sees the tenant's current knowledge so it
11	// proposes supersessions instead of duplicates, an explicit skip token keeps
12	// empty sources from producing empty review work, and a refusal gate keeps
13	// model apologies from ever being mistaken for knowledge.
14	
15	export interface KnownEntity {
16	  id: string;
17	  kind: "engagement" | "organization" | "person";
18	  name: string;
19	}
20	
21	export interface KnownFact {
22	  /** Display name of the anchoring entity, for the model's context only. */
23	  anchor: string;
24	  category: FactCategory;
25	  id: string;
26	  text: string;
27	}
28	
29	export interface ExtractionPromptInput {
30	  capturedAt: Date;
31	  capturedBy: string;
32	  content: string;
33	  /**
34	   * Reviewer-supplied steer for a re-extraction pass. Trusted: it comes from
35	   * an authenticated reviewer inside the tenant, not from ingested source
36	   * content, so instructions.md's "treat retrieved content as data" rule
37	   * (which governs fact text from outside email/transcripts) does not apply
38	   * to it.
39	   */
40	  hint?: string;
41	  knownEntities: KnownEntity[];
42	  knownFacts: KnownFact[];
43	  sourceType: "email" | "manual" | "voice";
44	}
45	
46	const hexObjectId = z.string().regex(/^[0-9a-f]{24}$/);
47	
48	export const llmEntityDraftSchema = z.object({
49	  data: z.record(z.string(), z.unknown()),
50	  draftId: z.string().min(1),
51	  entityType: z.enum(["organization", "person", "engagement"]),
52	});
53	export type LlmEntityDraft = z.infer<typeof llmEntityDraftSchema>;
54	
55	export const llmFactDraftSchema = z.object({
56	  anchors: z
57	    .object({
58	      engagementDraftId: z.string().optional(),
59	      engagementId: hexObjectId.optional(),
60	      organizationDraftId: z.string().optional(),
61	      organizationId: hexObjectId.optional(),
62	      personDraftId: z.string().optional(),
63	      personId: hexObjectId.optional(),
64	    })
65	    .refine((anchors) => Object.values(anchors).some(Boolean), {
66	      message: "A fact must anchor to an entity or entity draft",
67	    }),
68	  category: z.enum(factCategoryValues),
69	  confidence: z.number().min(0).max(1),
70	  supersedes: z.array(hexObjectId).optional(),
71	  text: z.string().min(1),
72	});
73	export type LlmFactDraft = z.infer<typeof llmFactDraftSchema>;
74	
75	// Strict on purpose: candidate objects are fished out of possibly-narrated
76	// model output, and with loose objects + defaults ANY {} would validate as
77	// an empty proposal (a live DeepSeek run turned a narration fragment into a
78	// false skip that way). At least one recognized key must be present.
79	export const llmExtractionSchema = z.union([
80	  z.strictObject({
81	    reason: z.string().default(""),
82	    skip: z.literal(true),
83	  }),
84	  z
85	    .strictObject({
86	      entities: z.array(llmEntityDraftSchema).optional(),
87	      facts: z.array(llmFactDraftSchema).optional(),
88	    })
89	    .refine((data) => data.entities !== undefined || data.facts !== undefined, {
90	      message: "A proposal needs an entities or facts key",
91	    }),
92	]);
93	
94	// Loose ONLY in the element types (each element is validated individually in
95	// parseExtractionResponse, so one malformed draft can no longer sink the
96	// whole reply). Still a strictObject union that requires a recognized key,
97	// because that is what stops a bare `{}` in the narration from validating
98	// as an empty proposal — see llmExtractionSchema's comment above.
99	const looseExtractionSchema = z.union([
100	  z.strictObject({
101	    reason: z.string().default(""),
102	    skip: z.literal(true),
103	  }),
104	  z
105	    .strictObject({
106	      entities: z.array(z.unknown()).optional(),
107	      facts: z.array(z.unknown()).optional(),
108	    })
109	    .refine((data) => data.entities !== undefined || data.facts !== undefined, {
110	      message: "A proposal needs an entities or facts key",
111	    }),
112	]);
113	
114	export const rejectedDraftSchema = z.object({
115	  /** What the model emitted, verbatim, so a reviewer can read it. */
116	  raw: z.unknown(),
117	  /** Why it failed validation, from the Zod error. Must name the field. */
118	  reason: z.string().min(1),
119	});
120	export type RejectedDraft = z.infer<typeof rejectedDraftSchema>;
121	
122	export type ParsedExtraction =
123	  | { kind: "failure"; reason: string }
124	  | {
125	      kind: "proposal";
126	      entities: LlmEntityDraft[];
127	      facts: LlmFactDraft[];
128	      rejected: RejectedDraft[];
129	    }
130	  | { kind: "skip"; reason: string };
131	
132	// The path is what makes a reject reason actionable ("anchors.personId:
133	// expected string, received array" vs. a bare "Invalid input") — a reviewer
134	// needs to know which field was wrong, not just that something was.
135	const describeZodError = (error: z.ZodError): string =>
136	  error.issues
137	    .map((issue) => `${issue.path.join(".")}: ${issue.message}`)
138	    .join(", ");
139	
140	export const buildExtractionPrompt = ({
141	  capturedAt,
142	  capturedBy,
143	  content,
144	  hint,
145	  knownEntities,
146	  knownFacts,
147	  sourceType,
148	}: ExtractionPromptInput): string => {
149	  const entityLines =
150	    knownEntities.length === 0
151	      ? "(none yet)"
152	      : knownEntities
153	          .map((entity) => `${entity.id} | ${entity.kind} | ${entity.name}`)
154	          .join("\n");
155	  const factLines =
156	    knownFacts.length === 0
157	      ? "(none yet)"
158	      : knownFacts
159	          .map(
160	            (fact) =>
161	              `${fact.id} | ${fact.anchor} | ${fact.category} | ${fact.text}`
162	          )
163	          .join("\n");
164	  // Interpolated as-is, unlike `content` below: this is reviewer input from
165	  // inside the tenant, not ingested source material, so it is trusted rather
166	  // than treated as data to quote (see the field comment on `hint`).
167	  const hintBlock =
168	    hint === undefined
169	      ? ""
170	      : `\nReviewer-supplied context (trusted, from a signed-in reviewer of this tenant):\n${hint}\n`;
171	
172	  return `You extract structured knowledge from business communications (German or English) for a company knowledge base. Reviewers confirm every item, so propose only what the source actually supports.
173	
174	Known entities (id | type | name):
175	${entityLines}
176	
177	Currently valid facts (id | anchor | category | text):
178	${factLines}
179	${hintBlock}
180	Source (type: ${sourceType}, captured by ${capturedBy} at ${capturedAt.toISOString()}):
181	---
182	${content}
183	---
184	
185	Return ONLY JSON, no markdown fences, in exactly one of these two shapes:
186	
187	1. Knowledge found:
188	{"entities": [{"draftId": "person-1", "entityType": "organization"|"person"|"engagement", "data": {"name": "...", ...}}], "facts": [{"text": "...", "category": "...", "confidence": 0.0-1.0, "anchors": {...}, "supersedes": ["<fact id>"]}]}
189	
190	2. Nothing worth recording (greetings, scheduling chatter, no business knowledge):
191	{"skip": true, "reason": "..."}
192	
193	Rules:
194	- Anchor each fact via "anchors": use a known entity id ({"organizationId": "<id>"}, {"personId": "<id>"}, {"engagementId": "<id>"}) when the name clearly matches a known entity; otherwise add an entity draft and reference it ({"personDraftId": "person-1"}).
195	- If a fact updates or contradicts a currently valid fact, list that fact's id in "supersedes". Do not re-state known facts unless they changed.
196	- Categories: ${factCategoryValues.join(" | ")}.
197	- Keep each fact one self-contained sentence in the source's language.
198	- Only ids from the lists above may appear as anchor ids or in "supersedes".`;
199	};
200	
201	export const parseExtractionResponse = (raw: string): ParsedExtraction => {
202	  const text = stripFences(raw);
203	  if (REFUSAL_REGEX.test(text)) {
204	    return { kind: "failure", reason: `model refused: ${text.slice(0, 200)}` };
205	  }
206	  const data = extractLastValidObject(text, looseExtractionSchema);
207	  if (data === undefined) {
208	    return {
209	      kind: "failure",
210	      reason: `no schema-valid JSON object in reply: ${text.slice(0, 200)}`,
211	    };
212	  }
213	  if ("skip" in data) {
214	    return { kind: "skip", reason: data.reason };
215	  }
216	
217	  const entities: LlmEntityDraft[] = [];
218	  const facts: LlmFactDraft[] = [];
219	  const rejected: RejectedDraft[] = [];
220	
221	  for (const draft of data.entities ?? []) {
222	    const result = llmEntityDraftSchema.safeParse(draft);
223	    if (result.success) {
224	      entities.push(result.data);
225	    } else {
226	      rejected.push({ raw: draft, reason: describeZodError(result.error) });
227	    }
228	  }
229	  for (const draft of data.facts ?? []) {
230	    const result = llmFactDraftSchema.safeParse(draft);
231	    if (result.success) {
232	      facts.push(result.data);
233	    } else {
234	      rejected.push({ raw: draft, reason: describeZodError(result.error) });
235	    }
236	  }
237	
238	  // Nothing usable at all: an empty reply is a skip, but a reply whose every
239	  // draft was malformed is a FAILURE — it deserves a retry, unlike a
240	  // judgment that there was nothing to record.
241	  if (entities.length === 0 && facts.length === 0) {
242	    return rejected.length > 0
243	      ? {
244	          kind: "failure",
245	          reason: `every draft failed validation: ${rejected
246	            .map((r) => r.reason)
247	            .join("; ")}`,
248	        }
249	      : { kind: "skip", reason: "empty proposal" };
250	  }
251	  return { entities, facts, kind: "proposal", rejected };
252	};
253

