37	export interface ExtractionRunResult {
38	  proposalId?: ObjectId;
39	  reason?: string;
40	  status: "failed" | "proposed" | "retry" | "skipped";
41	}
42	
43	const CONTEXT_ENTITY_LIMIT = 200;
44	const CONTEXT_FACT_LIMIT = 50;
45	
46	const EXTRACTABLE_STATUSES = new Set(["extracting", "received", "transcribed"]);
47	
48	// Referential validation: the model may only use ids it was shown.
49	const validateReferences = (
50	  facts: LlmFactDraft[],
51	  knownEntityIds: Set<string>,
52	  knownFactIds: Set<string>,
53	  entityDraftIds: Set<string>
54	): string | null => {
55	  for (const [index, fact] of facts.entries()) {
56	    const anchorIds = [
57	      fact.anchors.engagementId,
58	      fact.anchors.organizationId,
59	      fact.anchors.personId,
60	    ];
61	    for (const id of anchorIds) {
62	      if (id !== undefined && !knownEntityIds.has(id)) {
63	        return `facts[${index}] anchors unknown entity id ${id}`;
64	      }
65	    }
66	    const draftRefs = [
67	      fact.anchors.engagementDraftId,
68	      fact.anchors.organizationDraftId,
69	      fact.anchors.personDraftId,
70	    ];
71	    for (const draftId of draftRefs) {
72	      if (draftId !== undefined && !entityDraftIds.has(draftId)) {
73	        return `facts[${index}] anchors entity draft "${draftId}", which is not in the reply`;
74	      }
75	    }
76	    for (const id of fact.supersedes ?? []) {
77	      if (!knownFactIds.has(id)) {
78	        return `facts[${index}] supersedes unknown fact id ${id}`;
79	      }
80	    }
81	  }
82	  return null;
83	};
84	
85	const toFactDraft = (fact: LlmFactDraft) => {
86	  const anchors: Record<string, unknown> = {};
87	  if (fact.anchors.engagementDraftId) {
88	    anchors.engagementDraftId = fact.anchors.engagementDraftId;
89	  }
90	  if (fact.anchors.engagementId) {
91	    anchors.engagementId = new ObjectIdCtor(fact.anchors.engagementId);
92	  }
93	  if (fact.anchors.organizationDraftId) {
94	    anchors.organizationDraftId = fact.anchors.organizationDraftId;
95	  }
96	  if (fact.anchors.organizationId) {
97	    anchors.organizationId = new ObjectIdCtor(fact.anchors.organizationId);
98	  }
99	  if (fact.anchors.personDraftId) {
100	    anchors.personDraftId = fact.anchors.personDraftId;
101	  }
102	  if (fact.anchors.personId) {
103	    anchors.personId = new ObjectIdCtor(fact.anchors.personId);
104	  }
105	  return {
106	    anchors,
107	    category: fact.category,
108	    confidence: fact.confidence,
109	    ...(fact.supersedes?.length
110	      ? { supersedes: fact.supersedes.map((hex) => new ObjectIdCtor(hex)) }
111	      : {}),
112	    text: fact.text,
113	  };
114	};
115	
116	const gatherContext = async (db: Db, tenantId: string) => {
117	  const { engagements, facts, organizations, people } = getCollections(db);
118	  const [orgDocs, personDocs, engagementDocs, factDocs] = await Promise.all([
119	    organizations.find({ tenantId }).limit(CONTEXT_ENTITY_LIMIT).toArray(),
120	    people.find({ tenantId }).limit(CONTEXT_ENTITY_LIMIT).toArray(),
121	    engagements.find({ tenantId }).limit(CONTEXT_ENTITY_LIMIT).toArray(),
122	    facts
123	      .find({ tenantId, ...currentlyValidFilter })
124	      .sort({ updatedAt: -1 })
125	      .limit(CONTEXT_FACT_LIMIT)
126	      .toArray(),
127	  ]);
128	
129	  const knownEntities: KnownEntity[] = [
130	    ...orgDocs.map((doc) => ({
131	      id: doc._id.toHexString(),
132	      kind: "organization" as const,
133	      name: doc.name,
134	    })),
135	    ...personDocs.map((doc) => ({
136	      id: doc._id.toHexString(),
137	      kind: "person" as const,
138	      name: doc.name,
139	    })),
140	    ...engagementDocs.map((doc) => ({
141	      id: doc._id.toHexString(),
142	      kind: "engagement" as const,
143	      name: doc.title,
144	    })),
145	  ];
146	
147	  const nameById = new Map(knownEntities.map((e) => [e.id, e.name]));
148	  const anchorName = (fact: (typeof factDocs)[number]): string => {
149	    const id =
150	      fact.anchors.personId ??
151	      fact.anchors.organizationId ??
152	      fact.anchors.engagementId;
153	    return (id && nameById.get(id.toHexString())) || "unknown";
154	  };
155	
156	  const knownFacts: KnownFact[] = factDocs.map((doc) => ({
157	    anchor: anchorName(doc),
158	    category: doc.category,
159	    id: doc._id.toHexString(),
160	    text: doc.text,
161	  }));
162	
163	  return { knownEntities, knownFacts };
164	};
165	
166	// Where a retryable failure returns the source to. An interrupted
167	// "extracting" has lost its original status; re-derive it from the type.
168	const restingStatusFor = (source: Source): Source["status"] => {
169	  if (source.status !== "extracting") {
170	    return source.status;
171	  }
172	  return source.type === "voice" ? "transcribed" : "received";
173	};
174	
175	const produceParsed = async (
176	  generate: RunExtractionOptions["generate"],
177	  prompt: string,
178	  context: UsageContext
179	): Promise<ParsedExtraction> => {
180	  try {
181	    return parseExtractionResponse(await generate(prompt, context));
182	  } catch (error) {
183	    return {
184	      kind: "failure",
185	      reason: `generate failed: ${error instanceof Error ? error.message : String(error)}`,
186	    };
187	  }
188	};
189	
190	/**
191	 * Proposal identity is per (source, generation). Generation 1 deliberately
192	 * keeps the original seed so every proposal written before re-extraction
193	 * existed keeps its id; only later generations get a suffix.
194	 */
195	export const proposalIdFor = (
196	  tenantId: string,
197	  sourceId: ObjectId,
198	  generation: number
199	): ObjectId =>
200	  deterministicId(
201	    generation <= 1
202	      ? `${tenantId}:${sourceId.toHexString()}:extraction`
203	      : `${tenantId}:${sourceId.toHexString()}:extraction:${generation}`
204	  );
205	
206	const guardExtractable = (source: Source): void => {
207	  if (!EXTRACTABLE_STATUSES.has(source.status)) {
208	    throw new Error(
209	      `Source status "${source.status}" is not extractable — expected received, transcribed, or extracting`
210	    );
211	  }
212	  if (!source.content) {
213	    throw new Error("Source has no content to extract from");
214	  }
215	};
216	
217	interface ProposalDocInput {
218	  generation: number;
219	  hint: string | undefined;
220	  proposalId: ObjectId;
221	  sourceId: ObjectId;
222	  tenantId: string;
223	  writtenAt: Date;
224	}
225	
226	const buildProposalDoc = (
227	  parsed: Extract<ParsedExtraction, { kind: "proposal" }>,
228	  {
229	    generation,
230	    hint,
231	    proposalId,
232	    sourceId,
233	    tenantId,
234	    writtenAt,
235	  }: ProposalDocInput
236	) =>
237	  proposalSchema.parse({
238	    _id: proposalId,
239	    createdAt: writtenAt,
240	    entityDrafts: parsed.entities,
241	    extractionGeneration: generation,
242	    factDrafts: parsed.facts.map(toFactDraft),
243	    kind: "ingestion",
244	    sourceId,
245	    status: "open",
246	    tenantId,
247	    updatedAt: writtenAt,
248	    ...(parsed.rejected.length > 0 ? { rejectedDrafts: parsed.rejected } : {}),
249	    ...(hint === undefined ? {} : { hint }),
250	  });
251	
252	const buildSkipProposalDoc = (
253	  reason: string,
254	  {
255	    generation,
256	    hint,
257	    proposalId,
258	    sourceId,
259	    tenantId,
260	    writtenAt,
261	  }: ProposalDocInput
262	) =>
263	  proposalSchema.parse({
264	    _id: proposalId,
265	    createdAt: writtenAt,
266	    entityDrafts: [],
267	    extractionGeneration: generation,
268	    factDrafts: [],
269	    kind: "ingestion",
270	    skipReason: reason,
271	    sourceId,
272	    status: "open",
273	    tenantId,
274	    updatedAt: writtenAt,
275	    ...(hint === undefined ? {} : { hint }),
276	  });
277	
278	// Both the proposal and the skip branches close out identically: the
279	// pipeline moves the source on to "proposed" and clears the failure budget.
280	const markSourceProposed = (
281	  sources: ReturnType<typeof getCollections>["sources"],
282	  sourceId: ObjectId,
283	  tenantId: string,
284	  writtenAt: Date
285	) =>
286	  sources.updateOne(
287	    { _id: sourceId, tenantId },
288	    {
289	      $set: { extractionAttempts: 0, status: "proposed", updatedAt: writtenAt },
290	      $unset: { error: "" },
291	    }
292	  );
293	
294	export const runExtraction = async (
295	  db: Db,
296	  tenantId: string,
297	  { generate, hint, maxAttempts = 3, sourceId }: RunExtractionOptions
298	): Promise<ExtractionRunResult> => {
299	  const { proposals, sources } = getCollections(db);
300	  const source = await sources.findOne({ _id: sourceId, tenantId });
301	  if (!source) {
302	    throw new Error(`Source ${sourceId.toHexString()} not found`);
303	  }
304	
305	  const generation = source.extractionGeneration ?? 1;
306	  const proposalId = proposalIdFor(tenantId, sourceId, generation);
307	
308	  // Resume after a crash between proposal insert and status update: the
309	  // proposal is the durable record, the status just needs healing. The
310	  // proposal may itself be a skip (skipReason set) — a crash between that
311	  // insert and markSourceProposed must still resume as "skipped", or the
312	  // sweep report misattributes it as a proposal.
313	  const existing = await proposals.findOne({ _id: proposalId, tenantId });
314	  if (existing) {
315	    if (source.status !== "proposed" && source.status !== "reviewed") {
316	      await sources.updateOne(
317	        { _id: sourceId, tenantId },
318	        { $set: { status: "proposed", updatedAt: new Date() } }
319	      );
320	    }
321	    return existing.skipReason
322	      ? { proposalId, reason: existing.skipReason, status: "skipped" }
323	      : { proposalId, status: "proposed" };
324	  }
325	
326	  guardExtractable(source);
327	  const restingStatus = restingStatusFor(source);
328	
329	  await sources.updateOne(
330	    { _id: sourceId, tenantId },
331	    { $set: { status: "extracting", updatedAt: new Date() } }
332	  );
333	
334	  const { knownEntities, knownFacts } = await gatherContext(db, tenantId);
335	  const prompt = buildExtractionPrompt({
336	    capturedAt: source.createdAt,
337	    capturedBy: source.capturedBy,
338	    content: source.content ?? "",
339	    hint,
340	    knownEntities,
341	    knownFacts,
342	    sourceType: source.type,
343	  });
344	
345	  let parsed = await produceParsed(generate, prompt, {
346	    correlationId: sourceId.toHexString(),
347	    operation: "extraction",
348	    tenantId,
349	  });
350	
351	  if (parsed.kind === "proposal") {
352	    const problem = validateReferences(
353	      parsed.facts,
354	      new Set(knownEntities.map((entity) => entity.id)),
355	      new Set(knownFacts.map((fact) => fact.id)),
356	      new Set(parsed.entities.map((draft) => draft.draftId))
357	    );
358	    if (problem) {
359	      parsed = { kind: "failure", reason: problem };
360	    }
361	  }
362	
363	  const writtenAt = new Date();
364	
365	  const docInput: ProposalDocInput = {
366	    generation,
367	    hint,
368	    proposalId,
369	    sourceId,
370	    tenantId,
371	    writtenAt,
372	  };
373	
374	  if (parsed.kind === "proposal") {
375	    await insertIgnoringDuplicate(
376	      proposals,
377	      buildProposalDoc(parsed, docInput)
378	    );
379	    await markSourceProposed(sources, sourceId, tenantId, writtenAt);
380	    return { proposalId, status: "proposed" };
381	  }
382	
383	  if (parsed.kind === "skip") {
384	    // Nothing worth reviewing — but the source and the reason survive, and
385	    // the proposal is what makes both visible and re-extractable. Closing
386	    // the source here (the previous behaviour) discarded the reason and put
387	    // the source permanently out of reach of the sweep.
388	    await insertIgnoringDuplicate(
389	      proposals,
390	      buildSkipProposalDoc(parsed.reason, docInput)
391	    );
392	    await markSourceProposed(sources, sourceId, tenantId, writtenAt);
393	    return { proposalId, reason: parsed.reason, status: "skipped" };
394	  }
395	
396	  const attempts = (source.extractionAttempts ?? 0) + 1;
397	  const exhausted = attempts >= maxAttempts;
398	  await sources.updateOne(
399	    { _id: sourceId, tenantId },
400	    {
401	      $set: {
402	        error: parsed.reason,
403	        extractionAttempts: attempts,
404	        status: exhausted ? "failed" : restingStatus,
405	        updatedAt: writtenAt,
406	      },
407	    }
408	  );
409	  return { reason: parsed.reason, status: exhausted ? "failed" : "retry" };
410	};
