1	"use client";
2	
3	import {
4	  Conversation,
5	  ConversationContent,
6	  ConversationEmptyState,
7	  ConversationScrollButton,
8	} from "@repo/design-system/components/ai-elements/conversation";
9	import {
10	  Message,
11	  MessageContent,
12	  MessageResponse,
13	} from "@repo/design-system/components/ai-elements/message";
14	import {
15	  PromptInput,
16	  PromptInputBody,
17	  PromptInputFooter,
18	  PromptInputSubmit,
19	  PromptInputTextarea,
20	} from "@repo/design-system/components/ai-elements/prompt-input";
21	import {
22	  Reasoning,
23	  ReasoningContent,
24	  ReasoningTrigger,
25	} from "@repo/design-system/components/ai-elements/reasoning";
26	import { Shimmer } from "@repo/design-system/components/ai-elements/shimmer";
27	import {
28	  Tool,
29	  ToolContent,
30	  ToolHeader,
31	  ToolInput,
32	  ToolOutput,
33	} from "@repo/design-system/components/ai-elements/tool";
34	import { useEveAgent } from "eve/react";
35	import { BrainIcon } from "lucide-react";
36	import { useCallback, useMemo } from "react";
37	import { type CitedFact, FactCitation } from "./fact-citation";
38	
39	// The model emits <fact id="…"/> inline. Streamdown strips unknown tags by
40	// default, so the tag and its one attribute have to be allow-listed explicitly
41	// — which also means nothing else the model invents can reach the DOM.
42	const ALLOWED_TAGS = { fact: ["id"] };
43	
44	interface ToolPart {
45	  errorText?: string;
46	  input?: unknown;
47	  output?: unknown;
48	  state?: string;
49	  type: string;
50	}
51	
52	const isSearchTool = (part: { type: string }) =>
53	  part.type === "tool-search-knowledge" ||
54	  part.type === "dynamic-tool" ||
55	  part.type.startsWith("tool-");
56	
57	/**
58	 * eve delivers tool results in the AI SDK result envelope
59	 * `{ type: "json" | "error-text" | …, value }`, so the payload lives one
60	 * level down. Unwrap defensively — a bare payload passes through untouched.
61	 */
62	const unwrapToolOutput = (
63	  output: unknown
64	): { errorText?: string; value?: unknown } => {
65	  if (output === null || typeof output !== "object") {
66	    return { value: output };
67	  }
68	  const { type, value } = output as { type?: unknown; value?: unknown };
69	  if (type === "error-text" || type === "error-json") {
70	    return {
71	      errorText: typeof value === "string" ? value : JSON.stringify(value),
72	    };
73	  }
74	  if (type === "json" || type === "text" || type === "content") {
75	    return { value };
76	  }
77	  return { value: output };
78	};
79	
80	/**
81	 * Collect every fact the agent has retrieved so far. Citations resolve against
82	 * tool output, never against the prose: the model can only cite what the
83	 * knowledge base actually handed it.
84	 */
85	const collectFacts = (
86	  messages: { parts: { output?: unknown; type: string }[] }[]
87	): Map<string, CitedFact> => {
88	  const byId = new Map<string, CitedFact>();
89	  for (const message of messages) {
90	    for (const part of message.parts) {
91	      if (!isSearchTool(part)) {
92	        continue;
93	      }
94	      const output = unwrapToolOutput(part.output).value as
95	        | { facts?: CitedFact[] }
96	        | undefined;
97	      for (const fact of output?.facts ?? []) {
98	        if (fact?.id) {
99	          byId.set(fact.id, fact);
100	        }
101	      }
102	    }
103	  }
104	  return byId;
105	};
106	
107	const thinkingMessage = (isStreaming: boolean, duration?: number) => {
108	  if (isStreaming || duration === 0) {
109	    return <Shimmer duration={1}>Denkt nach …</Shimmer>;
110	  }
111	  if (duration === undefined) {
112	    return <p>Kurz nachgedacht</p>;
113	  }
114	  return <p>{duration}s nachgedacht</p>;
115	};
116	
117	export const KnowledgeChat = () => {
118	  const agent = useEveAgent();
119	  const isBusy = agent.status === "submitted" || agent.status === "streaming";
120	
121	  // Covers the gap between sending and the first streamed part — once the
122	  // assistant's reasoning starts arriving, its own "Denkt nach …" takes over.
123	  const lastMessage = agent.data.messages.at(-1) as
124	    | { parts: unknown[]; role?: string }
125	    | undefined;
126	  const awaitingResponse =
127	    isBusy &&
128	    (lastMessage?.role !== "assistant" || lastMessage.parts.length === 0);
129	
130	  const facts = useMemo(
131	    () => collectFacts(agent.data.messages as never),
132	    [agent.data.messages]
133	  );
134	
135	  const components = useMemo(
136	    () => ({
137	      fact: ({ id }: { id?: string }) => <FactCitation facts={facts} id={id} />,
138	    }),
139	    [facts]
140	  );
141	
142	  // PromptInput owns the textarea and hands back the composed message, so the
143	  // composer state lives there rather than being mirrored here.
144	  const submit = useCallback(
145	    (message: { text?: string }) => {
146	      const text = message.text?.trim() ?? "";
147	      if (text.length === 0 || isBusy) {
148	        return;
149	      }
150	      // Rejections surface through agent.error, which the view renders; this
151	      // catch only keeps the promise from floating.
152	      agent.send({ message: text }).catch(() => undefined);
153	    },
154	    [agent, isBusy]
155	  );
156	
157	  return (
158	    <div className="mx-auto flex h-full w-full min-w-0 max-w-3xl flex-col gap-3">
159	      <Conversation className="min-h-0 flex-1 rounded-xl border">
160	        <ConversationContent
161	          // Center the empty state in the frame; harmless with messages
162	          // present, but overflowing content must not be justify-centered or
163	          // its top becomes unreachable.
164	          className={
165	            agent.data.messages.length === 0
166	              ? "min-h-full justify-center"
167	              : undefined
168	          }
169	        >
170	          {agent.data.messages.length === 0 ? (
171	            <ConversationEmptyState
172	              description="Jede Antwort zitiert die Fakten, auf denen sie beruht."
173	              icon={<BrainIcon className="size-8" />}
174	              title="Frag das Firmengedächtnis"
175	            />
176	          ) : null}
177	
178	          {agent.data.messages.map((message) => (
179	            <Message from={message.role} key={message.id}>
180	              <MessageContent>
181	                {message.parts.map((part, index) => {
182	                  if (part.type === "reasoning") {
183	                    const reasoning = part as { state?: string; text?: string };
184	                    return (
185	                      <Reasoning
186	                        className="w-full"
187	                        isStreaming={reasoning.state === "streaming"}
188	                        // biome-ignore lint/suspicious/noArrayIndexKey: stream parts have no stable id and are append-only
189	                        key={index}
190	                      >
191	                        <ReasoningTrigger
192	                          getThinkingMessage={thinkingMessage}
193	                        />
194	                        <ReasoningContent>
195	                          {reasoning.text ?? ""}
196	                        </ReasoningContent>
197	                      </Reasoning>
198	                    );
199	                  }
200	
201	                  if (part.type === "text") {
202	                    return (
203	                      <MessageResponse
204	                        allowedTags={ALLOWED_TAGS}
205	                        components={components}
206	                        // biome-ignore lint/suspicious/noArrayIndexKey: stream parts have no stable id and are append-only
207	                        key={index}
208	                      >
209	                        {part.text}
210	                      </MessageResponse>
211	                    );
212	                  }
213	
214	                  if (isSearchTool(part)) {
215	                    const tool = part as ToolPart;
216	                    const { errorText, value } = unwrapToolOutput(tool.output);
217	                    return (
218	                      <Tool
219	                        // Fixed width: inside the fit-content message column
220	                        // a percentage width would grow with every streamed
221	                        // line of prose beneath it.
222	                        className="w-96 max-w-full"
223	                        // biome-ignore lint/suspicious/noArrayIndexKey: see above
224	                        key={index}
225	                      >
226	                        <ToolHeader
227	                          state={tool.state as never}
228	                          type={tool.type as never}
229	                        />
230	                        <ToolContent>
231	                          <ToolInput input={tool.input} />
232	                          <ToolOutput
233	                            errorText={tool.errorText ?? errorText}
234	                            output={value as never}
235	                          />
236	                        </ToolContent>
237	                      </Tool>
238	                    );
239	                  }
240	
241	                  return null;
242	                })}
243	              </MessageContent>
244	            </Message>
245	          ))}
246	
247	          {awaitingResponse ? (
248	            <Shimmer className="text-sm" duration={1.5}>
249	              Einen Moment …
250	            </Shimmer>
251	          ) : null}
252	        </ConversationContent>
253	        <ConversationScrollButton />
254	      </Conversation>
255	
256	      {agent.error ? (
257	        <p className="text-destructive text-sm">{agent.error.message}</p>
258	      ) : null}
